"""Generate a dependency-free static website. Run: python3 build.py."""
from pathlib import Path
import json, html
from seo import content_dates, save_dates, readable_date, breadcrumbs, breadcrumb_schema, graph, faq_html, with_contents, author_box
from seo_content import SERVICES, GUIDE_META, EXTRA_GUIDES, HOME_FAQS
from build_illustrations import build as build_illustrations
build_illustrations()
ROOT = Path(__file__).parent
DIST = ROOT / 'dist'
CONFIG = json.loads((ROOT / 'site-config.json').read_text())
ORIGIN = CONFIG['origin'].rstrip('/')
EMAIL = CONFIG['email']
FORM = CONFIG['formspree']
esc = html.escape
PAGES = []
COFFEE = (ROOT/'templates/illustrations/coffee.svg').read_text()

def header():
    return '<a class="skip" href="#main">Skip to content</a><header class="header"><div class="nav-panel"><a class="brand" href="/" aria-label="Ben Young home"><svg class="brand-scribble" viewBox="0 0 56 48" aria-hidden="true"><path d="M10 5C7 16 8 29 10 35M10 26C16 15 29 18 27 29S9 40 10 27M37 16C31 30 43 32 48 18M49 16C45 29 44 44 31 42"/></svg><span>Ben Young</span></a><nav aria-label="Main navigation"><a href="/#how-i-help">How I help</a><a href="/#my-story">My story</a><span class="nav-place">Melbourne, AU</span></nav></div><a class="nav-cta" href="/#contact" aria-label="Talk to Ben"><b class="cta-label">Talk to Ben</b><b class="cta-short" aria-hidden="true">Talk to Ben</b> <span aria-hidden="true">↗</span></a></header>'

def footer():
    links = ''.join(f'<a href="/services/{service["slug"]}/">{service["name"]}</a>' for service in SERVICES)
    return '<div class="wrap"><footer class="footer"><a class="footer-name" href="/">Ben Young</a><span>AI consulting for small businesses &amp; trades.<br>Melbourne, Australia · © 2026</span><div class="footer-links">'+links+'<a href="/guides/">Practical AI guides</a><a href="/case-study/">My business story</a><a href="/privacy/">Privacy</a><button type="button" data-analytics-preferences hidden>Turn off analytics</button><a href="mailto:' + EMAIL + '">Email Ben ↗</a></div></footer></div>'

def contact():
    return f'''<div class="contact-shell"><section class="contact-section section-round" id="contact" aria-labelledby="contact-title"><div class="wrap contact-grid"><div class="contact-intro"><span class="eyebrow">Melbourne? Let’s grab a coffee.</span><h2 id="contact-title">Let’s find your<br>first fix.</h2><p>Tell me what’s taking too long. I’ll reply to arrange a coffee or call and talk through a practical place to start.</p><div class="coffee-art">{COFFEE}</div><p class="meeting-note">Melbourne in person. Anywhere over a call.</p></div><form id="contact-form" action="{FORM}" method="POST"><h3>Talk to Ben <span aria-hidden="true">↙</span></h3><input type="hidden" name="_subject" value="New enquiry — Ben Young"><div class="hp" aria-hidden="true"><label for="website">Leave this field empty</label><input id="website" name="_gotcha" tabindex="-1" autocomplete="off"></div><div class="form-pair"><div class="field"><label for="name">Your name</label><input id="name" name="name" autocomplete="name" placeholder="First and last name" required maxlength="120"></div><div class="field"><label for="email">Your email</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@yourbusiness.com.au" required maxlength="254"></div></div><div class="field"><label for="business">Your business <small>(optional)</small></label><input id="business" name="business" autocomplete="organization" placeholder="Business name" maxlength="180"></div><div class="field"><label for="message">What would you like to make easier?</label><textarea id="message" name="message" placeholder="We keep entering the same job details into…" required minlength="10" maxlength="5000"></textarea></div><button class="button" type="submit">Send to Ben <span class="arrow" aria-hidden="true">↗</span></button><p class="form-note">Your details are used to reply to this enquiry. <a href="/privacy/">Privacy</a>.</p><p class="form-status" id="form-status" role="status" aria-live="polite" tabindex="-1"></p><a class="email-link" href="mailto:{EMAIL}">Or email {EMAIL} ↗</a></form></div></section></div>'''

def page(path, title, description, content, schema=None, noindex=False, dates=None):
    url = ORIGIN + path
    dates = dates or content_dates(path, title + description + content)
    structured = json.dumps(graph(ORIGIN, EMAIL, path, title, description, dates, schema), ensure_ascii=False).replace('<','\\u003c')
    verification = ''.join(f'<meta name="{name}" content="{esc(CONFIG[key],quote=True)}">' for name,key in [('google-site-verification','google_site_verification'),('msvalidate.01','bing_site_verification')] if CONFIG.get(key))
    scripts = '<script src="/assets/contact.js?v=5" defer></script><script src="/assets/living-art.js?v=2" defer></script><script src="/assets/motion.js?v=10" defer></script>' if 'id="contact-form"' in content else ''
    if CONFIG.get('google_analytics_id'):
        scripts += f'<script src="/assets/analytics.js?v=2" data-analytics-id="{esc(CONFIG["google_analytics_id"],quote=True)}" defer></script>'
    navigation = header().replace('href="/#contact"', 'href="#contact"') if 'id="contact-form"' in content else header()
    doc = f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)}</title><meta name="description" content="{esc(description,quote=True)}"><meta name="robots" content="{'noindex,follow' if noindex else 'index,follow,max-image-preview:large'}">{verification}<link rel="canonical" href="{url}"><meta name="theme-color" content="#9bce64"><meta property="og:type" content="{'article' if any(n.get('@type') == 'Article' for n in schema or []) else 'website'}"><meta property="og:locale" content="en_AU"><meta property="og:site_name" content="Ben Young"><meta property="og:title" content="{esc(title,quote=True)}"><meta property="og:description" content="{esc(description,quote=True)}"><meta property="og:url" content="{url}"><meta property="og:image" content="{ORIGIN}/assets/ben-young-social-v2.jpg"><meta property="og:image:type" content="image/jpeg"><meta property="og:image:width" content="1200"><meta property="og:image:height" content="630"><meta property="og:image:alt" content="Ben Young — stop losing hours to business admin. AI consulting for Melbourne small businesses."><meta name="twitter:card" content="summary_large_image"><meta name="twitter:title" content="{esc(title,quote=True)}"><meta name="twitter:description" content="{esc(description,quote=True)}"><meta name="twitter:image" content="{ORIGIN}/assets/ben-young-social-v2.jpg"><meta name="twitter:image:alt" content="Ben Young — stop losing hours to business admin. AI consulting for Melbourne small businesses."><link rel="icon" href="/assets/favicon.svg?v=8" type="image/svg+xml"><link rel="preload" href="/assets/fonts/inter-tight.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="/assets/style.css?v=15"><script type="application/ld+json">{structured}</script>{scripts}</head><body>{navigation}{content}{footer()}</body></html>'''
    file = DIST / ('index.html' if path == '/' else path.strip('/') + '/index.html')
    file.parent.mkdir(parents=True, exist_ok=True)
    file.write_text(doc)
    if not noindex: PAGES.append(path)

home = (ROOT/'templates/home.html').read_text().replace('{{CONTACT}}', contact()).replace('{{CAST}}', (ROOT/'templates/illustrations/cast.svg').read_text()).replace('{{BUILDER}}', (ROOT/'templates/illustrations/builder.svg').read_text())

home = home.replace('{{HOME_FAQS}}', '<div class="faq-shell"><section class="home-questions section-round"><div class="wrap">' + faq_html(HOME_FAQS) + '</div></section></div>')
page('/', 'AI Consultant Melbourne for Small Business | Ben Young', 'Losing hours to business admin? Ben Young helps Melbourne small businesses and trades connect software, automate repetitive work and build custom apps.', home)

GUIDES = [
('getting-started-with-ai','Getting started','AI for small business: where do you actually start?','A practical starting point for Melbourne business owners who know AI could help but aren’t sure what to do first.', '''<p>When you’re running a small business, finding time to investigate AI is a job in itself. The useful starting point is the work your team repeats every week. Identify a task that takes too long, understand why, and decide what would make it better.</p><h2>Look for friction in an ordinary working day</h2><p>Ask the person answering enquiries, scheduling jobs or preparing invoices to walk you through yesterday. Where did they copy information? What did they chase? What sat waiting because only one person knew what to do?</p><p>Write down three tasks, how often each happens and roughly how long it takes. For a trade business, that might be turning site notes into reports, copying enquiry details into job software, or searching old emails for customer instructions.</p><h2>Separate AI tasks from simple automation</h2><p>Moving an approved customer address between two systems may only need an integration. Turning a messy set of job notes into a readable draft is a possible AI task. The distinction matters: a reliable, simple connection can be more useful than adding AI to a process that doesn’t need it.</p><h2>Choose one small pilot</h2><ol><li><strong>Define the task.</strong> Be specific about where it starts and finishes.</li><li><strong>Record a baseline.</strong> Measure time spent, errors or rework before changing anything.</li><li><strong>Choose a reviewer.</strong> Someone needs to check the output and flag mistakes.</li><li><strong>Try representative examples.</strong> Include incomplete notes and unusual jobs, not just easy cases.</li><li><strong>Compare the result.</strong> Count the review time as well as the time saved.</li></ol><h2>Bring the people who do the work into the decision</h2><p>A useful tool needs to fit the working day. If a technician has to fill in three extra screens to save someone else a few minutes, the whole process may be worse. Get feedback early and make it easy to report a problem.</p><div class="callout"><p><strong>For our first conversation:</strong> bring one example of repetitive work, a list of the systems involved and a rough idea of how often it happens. You don’t need a technical brief.</p></div><h2>A local starting point</h2><p>I work with Melbourne small businesses to turn a practical problem into a manageable first project. We can meet for coffee, walk through the workflow and discuss whether a connection, an AI-assisted step or a custom tool makes sense.</p>'''),
('ai-for-trade-businesses','Trades & field services','AI for trade businesses in Melbourne','Practical ways to reduce the admin between the office and the field, from job notes to customer updates.', '''<p>For a trade or field service business, the work doesn’t end when a job is finished. Notes, photos, reports, customer updates and invoices all need to follow. AI and connected systems can help with those handovers when they are designed around the people doing the work.</p><h2>Start at the handover between site and office</h2><p>Consider a technician finishing a job. The office may need the work completed, materials used, follow-up actions and customer instructions. If those details arrive across separate messages, someone has to piece them together.</p><p>A structured capture form can put the information in one place. An AI-assisted step could turn free-text notes into a draft report for review, while ordinary automation moves approved information into the next system.</p><h2>Three workflows worth examining</h2><ul><li><strong>Enquiries to jobs:</strong> organise incoming requests and prepare the information your office needs before scheduling.</li><li><strong>Site notes to reports:</strong> draft a readable summary from the notes your team supplies, with missing information flagged.</li><li><strong>Job completion to customer updates:</strong> prepare a message from approved job details, ready for a team member to check.</li></ul><p>These are possible applications to assess for your business, rather than a claim that every tool can perform them reliably out of the box.</p><h2>Keep judgement with the people who know the job</h2><p>An AI-generated draft can omit details or make mistakes. Your team should approve customer-facing reports, quotes and important changes. The workflow should preserve the original notes and make corrections straightforward.</p><h2>Design for real conditions</h2><p>Think about phones, gloves, patchy reception and the end of a busy day. A technically impressive system that is awkward on site won’t help much. Test with the devices your team uses and agree what happens when a connection or integration fails.</p><h2>Improve the existing setup before replacing it</h2><p>Your current job management software may already do most of what you need. Connecting it to another system or adding a small tool may solve the problem. If it consistently forces your team into workarounds, a <a href="/guides/custom-business-apps/">custom business app</a> is another option to examine.</p><p>I’m based in Melbourne and bring experience from building an in-house app for my own business. We can start with one specific office-to-field problem and work out the right first step.</p>'''),
('connect-business-systems','Systems integration','Connect your business systems and stop entering everything twice','Systems integration for Melbourne small businesses: make enquiries, jobs and invoicing work together.', '''<p>If your team types the same customer details into several systems, the cost is more than the time spent. Records can drift apart, updates can be missed and someone has to work out which version to trust. A systems integration gives information a clear route between the tools you use.</p><h2>Map the journey of one real job</h2><p>Start with an enquiry and follow it to completion. List the systems involved, what each one needs and who enters the information. Mark every point where someone copies, exports, imports or retypes data.</p><p>That map shows where a connection would help. It also exposes process gaps that software alone won’t fix, such as a job moving to invoicing before the completion information has been approved.</p><h2>Choose a source of truth</h2><p>Decide which system owns each piece of information. Your customer record might live in one place, while the job status belongs in another. If both systems can update the same field, you need a clear rule for resolving conflicts.</p><h2>Build for the exceptions</h2><ul><li><strong>Duplicate records:</strong> use stable identifiers so a retried request doesn’t create a second job.</li><li><strong>Missing details:</strong> hold incomplete records for review rather than silently dropping them.</li><li><strong>Connection failures:</strong> make failed transfers visible and provide a safe retry path.</li><li><strong>Permissions:</strong> give the integration only the access it needs.</li><li><strong>Changes:</strong> allow for tools changing their APIs or subscription features.</li></ul><h2>Where AI fits</h2><p>AI can help interpret an unstructured enquiry or prepare a draft summary. Once information is approved and structured, conventional automation is often the right way to move it. Keeping those steps separate makes the process easier to understand and test.</p><h2>What I need to assess your systems</h2><p>Bring the names of the tools you use, the handover that causes trouble and an example with personal details removed. We can check what each platform supports before promising a connection. Some tools restrict API access or require particular plans.</p><p>For a Melbourne trade business, the first useful project could be a single reliable handover between enquiries and jobs. You can keep using the software that works while improving the connection that doesn’t.</p>'''),
('ai-workflow-automation','Workflow automation','AI workflow automation for small business','Reduce repetitive admin with carefully scoped AI workflows, clear review steps and measurable results.', '''<p>AI workflow automation is most useful when it handles a defined part of a process. It might turn rough notes into a draft, sort incoming information or extract details for someone to review. A useful workflow also makes clear who checks the result and what happens if something goes wrong.</p><h2>Find a task with a repeatable input and output</h2><p>“Use AI in the business” is too broad to scope. “Prepare a draft job report from the technician’s notes” gives you something concrete to test. Define the input, the expected output and the information that must never be invented.</p><h2>An example: notes to a draft report</h2><ol><li>A team member submits their original notes.</li><li>The workflow checks that the required information is present.</li><li>AI prepares a draft using the supplied details.</li><li>A person compares the draft with the notes, corrects it and approves it.</li><li>The approved report is saved or passed to the next system.</li></ol><p>This is an illustrative workflow. The exact design depends on your tools, the quality of the notes and the consequences of a mistake.</p><h2>Measure the whole process</h2><p>Saving five minutes of writing isn’t a win if checking the result takes ten. Compare total handling time, errors, rework and how easily the team can use the process. Keep examples of failures so the workflow can improve.</p><h2>Make the boundaries explicit</h2><p>Decide what data the AI service receives, who can access it and how long it is retained. Keep unnecessary personal or confidential details out of prompts. Use human approval before important customer communications or changes to operational records.</p><h2>Start small, then extend what works</h2><p>One dependable workflow is a useful foundation. Once it works for ordinary and difficult cases, you can consider neighbouring tasks. If the problem is really duplicate entry between tools, start with <a href="/guides/connect-business-systems/">systems integration</a>.</p><p>I help Melbourne business owners scope and build practical improvements around their existing work. We can begin with a conversation about the admin that is taking time away from running your business.</p>'''),
('custom-business-apps','Custom software','Custom business apps built around how you work','Explore a custom app for your Melbourne small business, from a focused internal tool to a tailored job management system.', '''<p>Off-the-shelf software is built for many businesses. That can be a strength, until your team spends every day working around features that don’t fit. A custom business app can bring the information and workflows you need into a system designed around your operation.</p><h2>When custom software is worth considering</h2><ul><li>Your team repeatedly moves information between several tools.</li><li>Key processes live in spreadsheets because existing software cannot handle them well.</li><li>You pay for overlapping subscriptions but still rely on manual workarounds.</li><li>Small improvements depend on a vendor’s roadmap.</li></ul><p>These are reasons to investigate, not automatic reasons to replace everything. An integration or a smaller internal tool may be enough.</p><h2>Start with the core workflow</h2><p>For a trade business, the first version might cover a particular journey through enquiries, jobs and reporting. Define what the first release must do, what can wait and what stays in existing software. Keep the first scope small enough for your team to use and evaluate.</p><h2>Think beyond the first build</h2><p>A business app needs hosting, access controls, backups, maintenance and a way to recover from problems. Discuss source-code access, data exports, documentation, ongoing support and who is responsible for each part. Include those costs when comparing a custom app with subscriptions.</p><h2>Bring your team into the build</h2><p>The people who use the app know where the current process gets awkward. Let them try real tasks early, including incomplete information and unusual jobs. Their feedback should shape the next iteration.</p><div class="callout"><p><strong>My own experience:</strong> we replaced every SaaS app in my business with one in-house app and removed over $80,000 in annual subscriptions. That is my business’s result; the right scope and economics will be different for yours.</p></div><h2>Make migration a separate part of the plan</h2><p>Moving away from an established platform means dealing with exports, historical records, attachments and active jobs. A staged transition gives you a way to verify the new system before relying on it. Read the <a href="/guides/replace-job-management-software/">job management replacement guide</a> for a practical decision framework.</p><p>If you’re in Melbourne, we can meet for coffee and look at the workarounds your team has outgrown.</p>'''),
('replace-job-management-software','Software decisions','Should you replace your job management software?','A practical framework for trade businesses weighing up integrations, a different platform or a custom job management app.', '''<p>Replacing job management software is a business decision as much as a technical one. The subscription bill is visible; the time spent on workarounds, migration and ongoing support is easier to overlook. Compare the whole picture before deciding.</p><h2>Write down what isn’t working</h2><p>Be specific. Is scheduling awkward? Are job notes hard to find? Does the office re-enter data? Are you paying for several overlapping tools? Separate missing features from configuration or training problems. A change to the existing setup may solve more than you expect.</p><h2>Compare three routes</h2><ul><li><strong>Improve what you have:</strong> adjust processes, configuration or team training.</li><li><strong>Connect or extend it:</strong> integrate existing tools or build a small app around a missing workflow.</li><li><strong>Replace it:</strong> move to another platform or build a custom system when the case is strong enough.</li></ul><h2>Count the ongoing costs</h2><p>Compare subscriptions with build costs, hosting, AI usage, maintenance, support and future changes. Include the time your team will spend testing and learning. In my own business I removed over $80,000 in annual subscriptions, but that figure is subscription spend removed, not a calculation of net savings after running a custom app.</p><h2>Check the exit before choosing the destination</h2><p>Find out what the current platform can export, in what format and with which attachments. Check how customer records, job histories, photos and documents are linked. Do this before cancelling access or committing to a migration date.</p><h2>Move in stages</h2><ol><li>Define the records and workflows the new system must support.</li><li>Test an export and import using a representative sample.</li><li>Check totals, attachments, permissions and relationships between records.</li><li>Trial real work with a small group and resolve the problems they find.</li><li>Agree a cutover plan, backup and rollback approach.</li><li>Keep access to the historical information your business needs.</li></ol><h2>Ask who owns the next improvement</h2><p>Before committing, agree how future changes are requested, scoped and supported. For a custom system, clarify source-code access, documentation, data ownership and how another developer could take over.</p><p>The right decision may be to keep your current system. I help Melbourne businesses assess the practical options and build a solution when the case makes sense. <a href="/case-study/">Read what changed in my own business</a>.</p>''')]

GUIDES.extend(EXTRA_GUIDES)
GUIDE_SERVICE = {'getting-started-with-ai':'ai-workflow-automation','ai-for-trade-businesses':'ai-workflow-automation','connect-business-systems':'business-systems-integration','ai-workflow-automation':'ai-workflow-automation','custom-business-apps':'custom-business-apps','replace-job-management-software':'custom-business-apps','ai-consulting-cost':'ai-workflow-automation','reduce-business-admin':'business-systems-integration'}

def article(path,title,desc,body,category='Practical AI guide',related=True):
    slug = path.strip('/').split('/')[-1]
    meta_title, meta_desc = GUIDE_META.get(slug, ('How I Removed $80k in Annual SaaS Subscriptions | Ben Young', desc))
    dates = content_dates(path, title + meta_desc + body)
    crumbs = [('Home','/'), ('Guides','/guides/'), (title,None)] if path.startswith('/guides/') else [('Home','/'), ('My business story',None)]
    service = next((v for v in SERVICES if v['slug'] == GUIDE_SERVICE.get(slug, 'custom-business-apps')), SERVICES[0])
    related_guides = [g for g in GUIDES if g[0] != slug and (g[0] == service['guide'] or g[0] in ('getting-started-with-ai','ai-consulting-cost','reduce-business-admin'))][:3]
    related_html = '<div class="related"><h2>Keep exploring</h2>'+''.join(f'<a href="/guides/{g[0]}/">{g[2]} <span aria-hidden="true">↗</span></a>' for g in related_guides)+'</div>' if related else ''
    toc, body = with_contents(body)
    service_link = f'<a href="/services/{service["slug"]}/">{service["name"]} in Melbourne</a>'
    content=f'''<main id="main" class="wrap"><div class="article-hero">{breadcrumbs(crumbs)}<div class="eyebrow">{esc(category)} · Melbourne</div><h1>{esc(title)}</h1><p class="intro">{esc(desc)}</p><p class="byline">By <a href="/#my-story" rel="author">Ben Young</a> · Business owner &amp; AI consultant<br>Updated <time datetime="{dates['modified']}">{readable_date(dates['modified'])}</time></p></div><div class="article-layout"><article class="article-body">{toc}{body}{author_box()}{related_html}</article><aside class="sidebar"><h2>Want help putting this to work?</h2><p>{service_link}</p><p>Bring one task that takes too long. We’ll work out a practical first fix.</p><a class="button" href="/#contact">Talk to Ben <span aria-hidden="true">↗</span></a><p class="sidebar-note">Melbourne · Coffee or a call</p></aside></div></main>'''
    schema = [{'@type':'Article','@id':ORIGIN+path+'#article','headline':title,'description':meta_desc,'mainEntityOfPage':{'@id':ORIGIN+path+'#webpage'},'author':{'@id':ORIGIN+'/#ben'},'publisher':{'@id':ORIGIN+'/#business'},'datePublished':dates['published'],'dateModified':dates['modified'],'inLanguage':'en-AU'}, breadcrumb_schema(ORIGIN,path,crumbs)]
    page(path,meta_title,meta_desc,content,schema,dates=dates)

for service in SERVICES:
    path = '/services/' + service['slug'] + '/'
    crumbs = [('Home','/'), (service['name'],None)]
    service_body = service['body'] + faq_html(service['faqs']) + f'<p class="service-guide">Want to work through the options first? <a href="/guides/{service["guide"]}/">Read the practical guide</a>.</p>'
    content = f'''<main id="main"><div class="wrap"><div class="article-hero service-page-hero">{breadcrumbs(crumbs)}<p class="eyebrow">{service['name']} · Melbourne</p><h1>{service['heading']}</h1><p class="intro">{service['intro']}</p><a class="button service-enquiry" href="#contact">Talk to Ben <span class="arrow" aria-hidden="true">↗</span></a><p class="service-meeting">Melbourne coffee or a call. Start with one task.</p></div><div class="article-layout"><article class="article-body">{service_body}</article><aside class="sidebar"><h2>Business owner to business owner.</h2><p>I replaced the SaaS tools in my own business with one in-house app, removing over $80,000 in annual subscriptions.</p><a class="text-link" href="/case-study/">Read my story ↗</a><p class="sidebar-note">My own result. Your scope and costs will be different.</p></aside></div></div>{contact()}</main>'''
    page(path,service['title'],service['description'],content,[{'@type':'Service','@id':ORIGIN+path+'#service','name':service['name'],'serviceType':service['name'],'description':service['description'],'url':ORIGIN+path,'provider':{'@id':ORIGIN+'/#business'},'areaServed':{'@type':'City','name':'Melbourne'},'mainEntityOfPage':{'@id':ORIGIN+path+'#webpage'}},breadcrumb_schema(ORIGIN,path,crumbs)])

for slug,cat,title,desc,body in GUIDES: article('/guides/'+slug+'/',title,desc,body,cat)

case='''<p>In my own business, we replaced every SaaS app with one app built in-house. That removed over $80,000 in annual subscriptions and gave us a way to improve the software directly as our team found better ways to work.</p><h2>One app built around our business</h2><p>Our business now uses the in-house app in place of the SaaS tools we previously subscribed to. That experience is the foundation of my consulting work: I’ve made this change inside my own business and use the result with my own team.</p><h2>The number — and what it means</h2><div class="callout"><p><strong>Over $80,000 in annual subscriptions removed.</strong> This is the subscription spend cut from my business. It is not a claim that a custom app has no running costs, or that another business will save the same amount.</p></div><p>A fair comparison for your business needs to include development, hosting, AI usage, maintenance and ongoing support. The opportunity depends on your existing software costs and how your team works.</p><h2>The part I value most: the speed of improvement</h2><blockquote>“If a team member has an idea of what could be improved in the morning, by lunchtime it’s live.”</blockquote><p>That describes what is possible for improvements in our own app. Bigger changes still need scoping, testing and time. The useful shift is being able to act on a team member’s feedback directly.</p><h2>What this means for your business</h2><p>Your first step doesn’t have to be a complete replacement. It could be connecting two systems, drafting a report from job notes, or building a small tool for a workflow your current software handles poorly.</p><p>I can help assess the practical options and work with you on a defined project. If replacing your platform is on the table, start with <a href="/guides/replace-job-management-software/">the questions to ask before changing job management software</a>.</p><h2>Start with a conversation</h2><p>Tell me what takes too long or what your team keeps working around. I’m based in Melbourne and happy to meet for coffee. <a href="/#contact">Get in touch</a>.</p>'''
article('/case-study/','One in-house app. Over $80,000 in annual subscriptions removed.','How Ben Young replaced every SaaS app in his business with one in-house app, removing over $80,000 in annual subscriptions and making everyday changes faster.',case,'My own business')
